'use strict';
document.querySelector('.settings').insertBefore(Object.assign(document.createElement('section'),{className:'panel labels-panel',innerHTML:`<div class="section-heading"><span class="step">03</span><h2>航点标注</h2><span class="label-mode" id="label-mode">推荐</span></div><p class="label-intro">只列出当前地图中出发或到达过的机场。勾选控制文字，不影响机场点位和航线。</p><div class="label-empty" id="label-empty">添加或导入航班后，即可选择标注。</div><div id="label-picker" hidden><label for="label-search" class="sr-only">搜索可标注机场</label><input id="label-search" type="search" placeholder="搜索机场、城市或三字码"><div class="label-actions"><button id="labels-all" type="button">全部标注</button><button id="labels-none" type="button">全部取消</button><button id="labels-auto" type="button">恢复推荐</button></div><div class="label-options" id="label-options" role="group" aria-label="选择地图上显示文字的机场"></div><div class="label-count" id="label-count" aria-live="polite"></div></div>`}),document.querySelector('.settings .help'));
let labelAirports=null,labelChineseNames={};
const labelNamesReady=fetch('data/airport-zh.json?v=2').then(checkResponse).then(r=>r.json()).then(names=>{labelChineseNames=names;return names;}).catch(()=>({}));
function getMapLabels(data){if(!data)return [];const choices=Array.isArray(state.labelSelection)?state.labelSelection:[...Object.values(data.extremes),'CDG','DXB','IST','CAI','LAX','RDU'];return [...new Set(choices)].filter(code=>typeof code==='string'&&Object.prototype.hasOwnProperty.call(data.airports,code));}
function labelAirportName(code){const a=labelAirports?.airports[code];return labelChineseNames[code]||a?.city||a?.name||code;}
function updateLabelControls(data){labelAirports=data||null;$('label-picker').hidden=!data;$('label-empty').hidden=!!data;$('label-mode').textContent=Array.isArray(state.labelSelection)?'自定义':'推荐';if(!data){$('label-options').replaceChildren();$('label-count').textContent='';return;}const selected=new Set(getMapLabels(data)),query=$('label-search').value.trim().toLowerCase();const codes=Object.keys(data.airports).sort((a,b)=>data.airports[b].n-data.airports[a].n||a.localeCompare(b));const matches=codes.filter(code=>[code,labelAirportName(code),data.airports[code].city,data.airports[code].name].join(' ').toLowerCase().includes(query));const fragment=document.createDocumentFragment();for(const code of matches){const row=document.createElement('label');row.className='label-option';const input=document.createElement('input');input.type='checkbox';input.value=code;input.checked=selected.has(code);input.dataset.airportLabel=code;input.setAttribute('aria-label',`${labelAirportName(code)} ${code}`);input.addEventListener('change',()=>{if(!state.data?.airports[code])return;const next=new Set(getMapLabels(state.data));input.checked?next.add(code):next.delete(code);setMapLabels([...next]);});const text=document.createElement('span');const name=document.createElement('span');name.className='label-option-name';name.textContent=labelAirportName(code);const detail=document.createElement('span');detail.className='label-option-detail';detail.textContent=code+' · '+data.airports[code].n+' 次起降';text.append(name,detail);row.append(input,text);fragment.append(row);}if(!matches.length){const empty=document.createElement('span');empty.className='label-no-matches';empty.textContent='没有匹配的已到访机场';fragment.append(empty);}$('label-options').replaceChildren(fragment);$('label-count').textContent=`已标注 ${selected.size} / ${codes.length} 个航点${query?' · 搜索结果 '+matches.length+' 个':''}`;}
function setMapLabels(selection){state.labelSelection=selection;regenerate();}
$('label-search').addEventListener('input',()=>updateLabelControls(labelAirports));$('labels-all').addEventListener('click',()=>{if(state.data)setMapLabels(Object.keys(state.data.airports));});$('labels-none').addEventListener('click',()=>{if(state.data)setMapLabels([]);});$('labels-auto').addEventListener('click',()=>setMapLabels(null));
